options(stringsAsFactors=FALSE)
suppressPackageStartupMessages({library(data.table);library(edgeR);library(glmnet);library(pROC);library(ranger);library(xgboost)})
root <- "D:/PDAC_P1";out<-file.path(root,"analysis/14_prediction/endothelial_state_ml_comparison");dir.create(out,recursive=TRUE,showWarnings=FALSE)
features<-c("EPAS1","TACC1","MARCKS","HERPUD1");markers<-c("PECAM1","VWF","EMCN")
build<-function(mat,name){mat<-mat[!duplicated(rownames(mat)),,drop=FALSE]; avail<-intersect(c(features,markers),rownames(mat));mat<-mat[avail,,drop=FALSE];ms<-colMeans(t(scale(t(mat[intersect(markers,rownames(mat)),,drop=FALSE]))));q<-quantile(ms,c(.30,.70));lab<-ifelse(ms>=q[2],1L,ifelse(ms<=q[1],0L,NA_integer_));x<-t(mat[intersect(features,rownames(mat)),,drop=FALSE]);x<-scale(x);list(name=name,x=x,label=lab,marker=ms)}
cts<-readRDS(file.path(root,"analysis/01_tcga_qc/TCGA-PAAD_primary_tumor_counts_unstranded.rds"));ann<-readRDS(file.path(root,"analysis/01_tcga_qc/TCGA-PAAD_gene_annotation.rds"));sy<-ann$gene_name[match(rownames(cts),ann$gene_id)];keep<-!is.na(sy)&sy!="";cts<-cts[keep,,drop=FALSE];rownames(cts)<-make.unique(sy[keep]);sets<-list(TCGA_PAAD=build(cpm(DGEList(counts=cts),log=TRUE,prior.count=2),"TCGA-PAAD"))
geo<-file.path(root,"data/01_bulk/GSE71729/raw/GSE71729_series_matrix.txt.gz");l<-readLines(gzfile(geo));b<-grep("^!series_matrix_table_begin",l)[1];g<-fread(geo,skip=b-1);setnames(g,1,"gene");gm<-as.matrix(g[,-1]);rownames(gm)<-g$gene;sets$GSE71729<-build(gm,"GSE71729")
g6<-fread(file.path(root,"analysis/08_program_validation/GSE62452/GSE62452_RMA_gene_symbol.tsv"),data.table=FALSE,check.names=FALSE);rownames(g6)<-g6[[1]];g6<-as.matrix(g6[,-1]);sets$GSE62452<-build(g6,"GSE62452")
tr<-sets$TCGA_PAAD;ix<-which(!is.na(tr$label));x<-tr$x[ix,,drop=FALSE];y<-tr$label[ix];set.seed(20260903);fold<-sample(rep(1:5,length.out=length(y)));models<-c("EPAS1_logistic","elastic_net","ranger","xgboost");oof<-matrix(NA,nrow(x),length(models),dimnames=list(rownames(x),models))
fitall<-function(trainx,trainy,testx){lg<-glm(trainy~EPAS1,data=data.frame(trainy,trainx),family=binomial());en<-cv.glmnet(trainx,trainy,family="binomial",alpha=.5,nfolds=5,type.measure="auc");rf<-ranger(as.factor(trainy)~.,data=data.frame(trainy=as.factor(trainy),trainx),probability=TRUE,num.trees=1000,min.node.size=10,seed=20260903);dtr<-xgb.DMatrix(trainx,label=trainy);xb<-xgb.train(data=dtr,nrounds=60,params=list(objective="binary:logistic",eval_metric="auc",max_depth=2,eta=.05,subsample=.8,colsample_bytree=.8),verbose=0);cbind(EPAS1_logistic=predict(lg,data.frame(testx),type="response"),elastic_net=as.numeric(predict(en,testx,s="lambda.1se",type="response")),ranger=predict(rf,data.frame(testx))$predictions[,"1"],xgboost=predict(xb,xgb.DMatrix(testx)))}
for(k in 1:5)oof[fold==k,]<-fitall(x[fold!=k,,drop=FALSE],y[fold!=k],x[fold==k,,drop=FALSE])
final<-fitall(x,y,x);predrows<-list(data.table(dataset="TCGA-PAAD",sample=rownames(x),label=y,oof));perfs<-list(data.table(dataset="TCGA-PAAD",model=models,AUROC=sapply(models,function(m)as.numeric(auc(roc(y,oof[,m],quiet=TRUE))),simplify=TRUE)))
for(nm in c("GSE71729","GSE62452")){s<-sets[[nm]];j<-which(!is.na(s$label));pp<-fitall(x,y,s$x[j,,drop=FALSE]);predrows[[length(predrows)+1]]<-data.table(dataset=nm,sample=rownames(s$x)[j],label=s$label[j],pp);perfs[[length(perfs)+1]]<-data.table(dataset=nm,model=models,AUROC=sapply(models,function(m)as.numeric(auc(roc(s$label[j],pp[,m],quiet=TRUE))),simplify=TRUE))}
perf<-rbindlist(perfs);perf[,external_mean_AUROC:=mean(AUROC[dataset!="TCGA-PAAD"]),by=model];fwrite(perf,file.path(out,"endothelial_state_ml_performance.tsv"),sep="\t");fwrite(rbindlist(predrows,fill=TRUE),file.path(out,"endothelial_state_ml_predictions.tsv"),sep="\t")
en.final <- cv.glmnet(x,y,family="binomial",alpha=.5,nfolds=10,type.measure="auc")
beta <- as.matrix(coef(en.final,s="lambda.1se")); fwrite(data.table(feature=rownames(beta),coefficient=as.numeric(beta[,1])),file.path(out,"elastic_net_final_coefficients.tsv"),sep="\t")
# Exact SHAP for a linear logistic model: beta_j*x_j on the log-odds scale; x is cohort-z-standardized.
beta.feature <- beta[features,1]; shap <- sweep(x,2,beta.feature,"*"); shap.out <- list(data.table(dataset="TCGA-PAAD",sample=rownames(x),shap,check.names=FALSE))
for(nm in c("GSE71729","GSE62452")){s<-sets[[nm]];j<-which(!is.na(s$label));sh<-sweep(s$x[j,features,drop=FALSE],2,beta.feature,"*");shap.out[[length(shap.out)+1]]<-data.table(dataset=nm,sample=rownames(s$x)[j],sh,check.names=FALSE)}
fwrite(rbindlist(shap.out,fill=TRUE),file.path(out,"elastic_net_exact_linear_SHAP.tsv"),sep="\t")
best<-perf[dataset!="TCGA-PAAD",.(external_mean_AUROC=mean(AUROC)),by=model][order(-external_mean_AUROC)]; selected<-best[1]; simple<-best[model=="EPAS1_logistic"];decision<-if(simple$external_mean_AUROC>=selected$external_mean_AUROC-.02)"retain_EPAS1_logistic_for_parsimony"else paste0("retain_",selected$model)
writeLines(c("# Endothelial-state ML comparison","", "- Endpoint: top/bottom 30% vascular-marker state (PECAM1/VWF/EMCN); middle 40% excluded.","- Predictors fixed before modeling: EPAS1, TACC1, MARCKS and HERPUD1. Molecular variables were z-standardized within cohort to limit platform-scale differences.","- Internal evaluation: five-fold out-of-fold AUROC. External evaluation: GSE71729 and GSE62452 AUROC.","- Models were intentionally limited to one linear, one penalized linear and two non-linear learners; no broad algorithm sweep was performed.",paste0("- Selection rule: simplest model within 0.02 external mean AUROC of the leader. Decision: ",decision,"."),"- This is a molecular-state classifier, not a diagnostic or prognostic clinical model."),file.path(out,"endothelial_state_ml_report.md"))
